def AlphaNum_NumAlpha(input_string):
    alphabet = ['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm',
                'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z']
    alphabetnums = {chr(97+i): str(i+1) for i in range(26)}
    num_to_alpha = {str(i+1): alphabet[i] for i in range(26)}
    num_to_alpha['26'] = 'z'

    output = []
    i = 0
    n = len(input_string)

    while i < n:
        c = input_string[i]
        if c.isalpha():
            output.append(alphabetnums[c.lower()])
            i += 1
        else:
            j = i
            while j < n and input_string[j].isdigit():
                j += 1
            num_str = input_string[i:j]
            if num_str in num_to_alpha:
                output.append(num_to_alpha[num_str])
            else:
                output.append(num_to_alpha[num_str[:2]])
            i = j
    return ''.join(output)
